--- 系统功能解锁管理

---@type Singleton
local Singleton = import('Frame.Singleton')
---@class SystemToggleMgr : Singleton
---@field GetInstance fun(self:SystemToggleMgr):SystemToggleMgr
local SystemToggleMgr = Class("SystemToggleMgr", Singleton)
local KTool = CS.Engine.Lib.KTool
local UIEventProxy = CS.Engine.UI.UIEventProxy
local Toggle = CS.UnityEngine.UI.Toggle


local SystemToggle =  CS.Game.Native.Common.SystemToggle

function SystemToggleMgr:__init()
    self._allSystemBtns = {}
end

function SystemToggleMgr:__delete()
    self._allSystemBtns = {}
end

--[[
    @desc: 
    author:{author}
    time:2020-08-12 14:51:29
    --@btnGo:按钮go
	--@func:
    @return:
]]
function SystemToggleMgr:SetModelFunction(go, func)
    if not go then
        return
    end

    local systemToggleScr = KTool.GetComponent(go.gameObject, typeof(SystemToggle))
    --如果没有脚本不受管理，直接设置事件
    if not systemToggleScr then
        self:SetGoAction(go, func)
        return
    end

    local systemToggleId = checkString(systemToggleScr.id)
    --id是0不受控制
    if checkNumber(systemToggleId) == Constants.SystemToggleIds.None then
        self:SetGoAction(go, func)
        return
    end

    --表里没有也不受控制
    local vo = CfUtils.SystemToggleVo( systemToggleId)
    if not vo then
        self:SetGoAction(go, func)
        return
    end

    --如果是关闭
    if checkNumber(vo.switch) == Constants.ModelFunctionSwitch.Off then
        KTool.SetActive(go, false)
        return
    end

    local isUnlock = GameUtils.IsUnlocked(vo.unlockType, vo.unlockNum, vo.unlockId)
    --已解锁
    if isUnlock then
        --UIEventProxy.Create(go.gameObject).onPointerClick = func
        KTool.SetActive(go, true)
        self:SetGoAction(go, func)
    else
        --隐藏
        if checkNumber(vo.lockShowType) == Constants.ModelFunctionLockShowType.Hide then
            KTool.SetActive(go, false)
        --锁定展示
        elseif checkNumber(vo.lockShowType) == Constants.ModelFunctionLockShowType.LockShow then
            KTool.SetActive(go, true)
            self:SetGoAction(go, function()
                local isUnlock = GameUtils.IsUnlocked(vo.unlockType, vo.unlockNum, vo.unlockId)
                if not isUnlock then
                    GameUtils.Toast(GameUtils.GetUnlockDescription(vo.unlockType, vo.unlockNum, vo.unlockId))
                else
                    func()
                end
            end)
        end
    end

    self:_UpdateModelFunctionBtn(go, systemToggleId, isUnlock)
end

--[[
    @desc: 是否解锁了模块
    author:{author}
    time:2020-08-13 21:27:06
    --@systemToggleId: id
    @return:
]]
function SystemToggleMgr:IsUnLockModel(systemToggleId, noTips)
    systemToggleId = checkNumber(systemToggleId)
    local vo = CfUtils.SystemToggleVo( systemToggleId)
    if not vo then
        return false, localize("系统功能未找到_num_", {_num_ = systemToggleId})
    end

    --如果是关闭
    if checkNumber(vo.switch) == Constants.ModelFunctionSwitch.Off then
        return false, not noTips and localize("功能已关闭")
    end

    local isUnlock = GameUtils.IsUnlocked(vo.unlockType, vo.unlockNum, vo.unlockId)
    return isUnlock, not noTips and GameUtils.GetUnlockDescription(vo.unlockType, vo.unlockNum, vo.unlockId)
end

--更新按钮状态
function SystemToggleMgr:_UpdateModelFunctionBtn(btnGo, systemToggleId, isUnlock)
    if not btnGo then
        return
    end

    systemToggleId = checkString(systemToggleId)

    --go的全路径做key
    local k = KTool.GetRootPathName(btnGo.transform)

    local btnVo = self._allSystemBtns[k]
    if btnVo then
        --如果解锁状态发生了改变
        if not (isUnlock == btnVo.isUnlock) then
            btnVo.isUnlock = isUnlock
            self:DoUnLockAction(btnVo, btnGo)
        end
    else
        btnVo = self:GetBtnVo(systemToggleId, isUnlock)
        self._allSystemBtns[k] = btnVo
    end
end

function SystemToggleMgr:SetGoAction(go, func)
    if not go then
        return
    end

    if KTool.GetComponent(go.gameObject, typeof(Toggle)) then
        local tog = KTool.GetComponent(go.gameObject, typeof(Toggle))
        tog.onValueChanged:RemoveAllListeners()
        tog.onValueChanged:AddListener(func)
    else
        local eventProxy = UIEventProxy.Create(go.gameObject)
        eventProxy.onPointerClick = func
        eventProxy.onPointerDown = function()
            local animation = go.transform:GetComponent(typeof(CS.UnityEngine.Animation))
            if not KTool.IsNull(animation) then
                for _, animationState in pairs(animation) do
                    if animationState.name == "UI_Common_ButtonPressed" then
                        animation:Play("UI_Common_ButtonPressed")
                        break
                    end
                end

            end
        end
        eventProxy.onPointerUp = function()
            local animation = go.transform:GetComponent(typeof(CS.UnityEngine.Animation))
            if not KTool.IsNull(animation) then
                for _, animationState in pairs(animation) do
                    if animationState.name == "UI_Common_ButtonIdle" then
                        animation:Play("UI_Common_ButtonIdle")
                        break
                    end
                end
            end
        end
    end
end


--处理解锁的表现
function SystemToggleMgr:DoUnLockAction(btnVo, btnGo)
    --如果是未解锁
    if not btnVo.isUnlock then
        return
    end

    local vo = CfUtils.SystemToggleVo( btnVo.systemToggleId)
    if not vo then
        return
    end
    if checkNumber(vo.unlockShowType) == Constants.ModelFunctionUnLockShowType.None then
        --GameUtils.Toast(localize("新功能解锁了,解锁类型0，id: _num_", {_num_ = vo.id}), 300)
    elseif checkNumber(vo.unlockShowType) == Constants.ModelFunctionUnLockShowType.Dialog then
        --GameUtils.Toast(localize("新功能解锁，解锁类型1，id: _num_", {_num_ = vo.id}), 300)
    end
end

function SystemToggleMgr:GetBtnVo(systemToggleId, isUnlock)
    return {
        systemToggleId = checkString(systemToggleId),
        isUnlock = checkBool(isUnlock),
    }
end

---GetSystemToggleIds
---获得 系统功能表ids
---@param refId number 系统功能表 IdGroup Key
---@param unlockType number Constants.CommonUnlockType
function SystemToggleMgr:GetSystemToggleIds(unlockType, refId)
    ---@type SettingMgr
    local settingMgr = SettingMgr:GetInstance()
    ---@type TableML.TableFile
    local tableFile = settingMgr:Get(string.format("%s%s", AutoIds.IdSetting401, string.format("%sIDGroup", unlockType)))
    ---@type TableML.TableFileRow
    local row = tableFile:GetByPrimaryKey(refId, false)
    if row == nil then return end

    local systemToggleIds = parse_strings(parse_string(row, "ids"))
    return systemToggleIds
end

return SystemToggleMgr
